    },
    {
      "name": "aircraft_condition",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.75,
      "hallucination_observed": true,
      "rationale": "A new theme axis not present in originals, useful for grouping. High NULL rate correctly handles silent rows. But sample 2 says nothing about aircraft age/condition yet was labelled comfortable_aging, an invented specific; minor groundedness hit."
    },
    {
      "name": "customer_service",
      "analytical_usefulness": 0.45,
      "source_groundedness": 0.8,
      "hallucination_observed": true,
